create or replace function demo_desktop.registration_values(p_values jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$declare result jsonb:='{}';k text;v text;n numeric;begin
 if jsonb_typeof(p_values) is distinct from 'object' or p_values-array['name','phone','address','gisu','pyeong','amount','requirements','specialNotes','amount2023','amount2024','amount2025','amount2026']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['name','phone','address','gisu','requirements','specialNotes'] loop
  v:=demo_desktop.text_value(p_values,k,case when k in ('name','phone','address') then 4000 else 10000 end);
  result:=result||jsonb_build_object(k,v);
 end loop;
 foreach k in array array['pyeong','amount','amount2023','amount2024','amount2025','amount2026'] loop
  n:=demo_desktop.number_value(p_values,k,k='pyeong');result:=result||jsonb_build_object(k,n);
 end loop;
 return result;
end $$;
create or replace function demo_desktop.write_payment(p_owner uuid,p_workspace uuid,p_grave bigint,p_year integer,p_kind text,p_amount bigint,p_source text) returns bigint
language plpgsql set search_path='' as $$declare payment_id bigint;begin
 select p.id into payment_id from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=p_grave and p.year=p_year and p.kind=p_kind;
 if payment_id is null then
  payment_id:=demo_desktop.next_id(p_owner,p_workspace,'payments');
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(p_owner,p_workspace,payment_id,p_grave,p_year,p_kind,p_amount,jsonb_build_object('source',p_source));
 else update demo_desktop.payments set amount=p_amount,data=data||jsonb_build_object('source',p_source) where owner_id=p_owner and workspace_id=p_workspace and payments.id=payment_id;end if;
 return payment_id;
end $$;
create or replace function demo_desktop.register(p_owner uuid,p_workspace uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare v jsonb;cid bigint;gid bigint;y integer;amount bigint;year_now integer:=extract(year from clock_timestamp() at time zone 'Asia/Seoul');candidate record;status text:=coalesce(p_input->>'registrationStatus','registered');phone text;begin
 if p_input-array['type','values','registrationStatus','preparationId']<>'{}' or status not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
 v:=demo_desktop.registration_values(p_input->'values');
 if not exists(select from jsonb_each(v) where value<>'null'::jsonb) then perform demo_desktop.fail('invalid-input');end if;
 if p_input ? 'preparationId' then
 select * into candidate from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and id=(p_input->>'preparationId')::uuid and actor_id=auth.uid() and state='prepared' and target->'newCustomer'='true'::jsonb;
 if not found then perform demo_desktop.fail('conflict');end if;cid:=candidate.customer_id;gid:=candidate.grave_id;
 else cid:=demo_desktop.next_id(p_owner,p_workspace,'customers');gid:=demo_desktop.next_id(p_owner,p_workspace,'graves');end if;phone:=nullif(regexp_replace(v->>'phone','[^0-9]','','g'),'');
 insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(p_owner,p_workspace,cid,jsonb_build_object('name',v->'name','phone',phone,'phone_raw',v->'phone','phone_ok',case when v->>'phone' is null or phone~'^0[0-9]{8,10}$' then 1 else 0 end,'memo',v->'requirements','special_notes',v->'specialNotes','registration_status',status,'deleted_at',null,'created_at',clock_timestamp()::text));
 insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(p_owner,p_workspace,gid,cid,jsonb_build_object('address',v->'address','gisu',v->'gisu','pyeong',v->'pyeong','is_active',1,'deleted_at',null,'created_at',clock_timestamp()::text));
 for y in 2023..2026 loop
  amount:=(v->>('amount'||y))::bigint;
  if y=year_now and v->>'amount' is not null then
   if amount is not null and amount<>(v->>'amount')::bigint then perform demo_desktop.fail('invalid-input');end if;amount:=(v->>'amount')::bigint;
  end if;
  if amount is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,y,'annual',amount,'desktop');end if;
 end loop;
 if year_now not between 2023 and 2026 and v->>'amount' is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,year_now,'annual',(v->>'amount')::bigint,'desktop');end if;
 if status='registered' then insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,data) values(p_owner,p_workspace,gen_random_uuid(),year_now,cid,gid,'proceed',jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline',''));end if;
 if p_input ? 'preparationId' then perform demo_desktop.connect_earth(p_owner,p_workspace,null,p_input,true);end if;
 return jsonb_build_object('customerId',cid,'graveId',gid);
end $$;
create or replace function demo_desktop.edit_values(p_values jsonb,p_customer jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$declare adjusted jsonb:=p_values;v jsonb;k text;column_name text;begin
 if jsonb_typeof(p_values) is distinct from 'object' or p_values-array['name','phone','address','gisu','pyeong','requirements','specialNotes']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['requirements','specialNotes'] loop
  column_name:=case k when 'requirements' then 'memo' else 'special_notes' end;
  if not p_values ? k or p_values->>k is not distinct from coalesce(p_customer->>column_name,'') then adjusted:=adjusted||jsonb_build_object(k,'');end if;
 end loop;
 v:=demo_desktop.registration_values(adjusted);
 foreach k in array array['requirements','specialNotes'] loop
  column_name:=case k when 'requirements' then 'memo' else 'special_notes' end;
  if not p_values ? k or p_values->>k is not distinct from coalesce(p_customer->>column_name,'') then v:=v||jsonb_build_object(k,p_customer->column_name);end if;
 end loop;
 return v;
end $$;

create or replace function demo_desktop.update_customers(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare i jsonb;v jsonb;customer jsonb;grave jsonb;cid bigint;gid bigint;k text;phone text;payment jsonb;pid bigint;amount bigint;shared jsonb:='{}';targets text[]:='{}';entity text;canonical jsonb;rows jsonb:='[]';begin
 if p_input-array['type','inputs']<>'{}' or jsonb_typeof(p_input->'inputs') is distinct from 'array' or jsonb_array_length(p_input->'inputs') not between 1 and 20000 then perform demo_desktop.fail('invalid-input');end if;
 for i in select value from jsonb_array_elements(p_input->'inputs') loop
  if jsonb_typeof(i) is distinct from 'object' or i-array['customerId','graveId','revision','values','payments']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  cid:=(i->>'customerId')::bigint;gid:=(i->>'graveId')::bigint;
  if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from i->>'revision' then perform demo_desktop.fail('conflict');end if;
  entity:=coalesce(cid::text,'')||':'||coalesce(gid::text,'');if entity=any(targets) then perform demo_desktop.fail('invalid-input');end if;targets:=array_append(targets,entity);
  if cid is not null then
   perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
   select data into customer from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
   v:=demo_desktop.edit_values(i->'values',customer);
   if nullif(customer->>'deleted_at','') is not null then perform demo_desktop.fail('conflict');end if;
   canonical:=jsonb_build_object('name',case when i->'values' ? 'name' then demo_desktop.text_value(i->'values','name',4000) else customer->>'name' end,
    'phone',case when i->'values' ? 'phone' then demo_desktop.text_value(i->'values','phone',4000) else coalesce(customer->>'phone_raw',customer->>'phone') end,
    'requirements',v->'requirements',
    'specialNotes',v->'specialNotes');
   if shared ? cid::text and shared->cid::text<>canonical then perform demo_desktop.fail('conflict');end if;shared:=shared||jsonb_build_object(cid::text,canonical);
  end if;
  if gid is not null and exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  v:=demo_desktop.edit_values(i->'values',coalesce(customer,'{}'::jsonb));
  if jsonb_typeof(i->'payments') is distinct from 'array' then perform demo_desktop.fail('invalid-input');end if;
 end loop;
 for i in select value from jsonb_array_elements(p_input->'inputs') loop
  cid:=(i->>'customerId')::bigint;gid:=(i->>'graveId')::bigint;
  select data into customer from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
  v:=demo_desktop.edit_values(i->'values',coalesce(customer,'{}'::jsonb));
  if cid is null and exists(select from jsonb_each(v) where key in ('name','phone','requirements','specialNotes') and value<>'null'::jsonb) then
   cid:=demo_desktop.next_id(p_owner,p_workspace,'customers');insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(p_owner,p_workspace,cid,'{}');
   update demo_desktop.graves set customer_id=cid where owner_id=p_owner and workspace_id=p_workspace and id=gid;
  end if;
  if cid is not null then
   select data into customer from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
   foreach k in array array['name','requirements','specialNotes'] loop
    if i->'values' ? k then customer:=customer||jsonb_build_object(case k when 'requirements' then 'memo' when 'specialNotes' then 'special_notes' else k end,v->k);end if;
   end loop;
   if i->'values' ? 'phone' then phone:=nullif(regexp_replace(v->>'phone','[^0-9]','','g'),'');customer:=customer||jsonb_build_object('phone_raw',v->'phone','phone',phone,'phone_ok',case when v->>'phone' is null or phone~'^0[0-9]{8,10}$' then 1 else 0 end);end if;
   update demo_desktop.customers set data=customer where owner_id=p_owner and workspace_id=p_workspace and id=cid;
  end if;
  if gid is null and (v->>'address' is not null or v->>'gisu' is not null or v->>'pyeong' is not null or exists(select from jsonb_array_elements(i->'payments') p where nullif(p->>'amount','') is not null)) then
   gid:=demo_desktop.next_id(p_owner,p_workspace,'graves');insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(p_owner,p_workspace,gid,cid,jsonb_build_object('is_active',1));
  end if;
  if gid is not null then
   select data into grave from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid;
   foreach k in array array['address','gisu','pyeong'] loop if i->'values' ? k then grave:=grave||jsonb_build_object(k,v->k);end if;end loop;
   update demo_desktop.graves set data=grave where owner_id=p_owner and workspace_id=p_workspace and id=gid;
   for payment in select value from jsonb_array_elements(i->'payments') loop
    if jsonb_typeof(payment) is distinct from 'object' or payment-array['id','grave_id','year','kind','amount','paid_at','method','source','note']<>'{}' or jsonb_typeof(payment->'year') is distinct from 'number' or (payment->>'year')::numeric not between 1 and 9999 or (payment->>'year')::numeric<>trunc((payment->>'year')::numeric) or jsonb_typeof(payment->'kind') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
    amount:=demo_desktop.number_value(payment,'amount');pid:=(payment->>'id')::bigint;
    if pid is not null then
     if amount is null or not exists(select from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.id=pid and p.grave_id=gid and p.year=(payment->>'year')::int and p.kind=payment->>'kind') then perform demo_desktop.fail('conflict');end if;
     update demo_desktop.payments set amount=update_customers.amount where owner_id=p_owner and workspace_id=p_workspace and id=pid;
    elsif amount is not null then
     if exists(select from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=gid and p.year=(payment->>'year')::int and p.kind=payment->>'kind') then perform demo_desktop.fail('conflict');end if;
     perform demo_desktop.write_payment(p_owner,p_workspace,gid,(payment->>'year')::int,payment->>'kind',amount,'desktop');
    end if;
   end loop;
  end if;
  perform demo_desktop.bump(p_owner,p_workspace,cid,gid);rows:=rows||jsonb_build_array(jsonb_build_object('customerId',cid,'graveId',gid));
 end loop;
 return jsonb_build_object('rows',rows);
end $$;
create or replace function demo_desktop.archive(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare cid bigint:=(p_input->>'customerId')::bigint;gid bigint:=(p_input->>'graveId')::bigint;at text;begin
 if p_input-array['type','customerId','graveId','revision','archived']<>'{}' or jsonb_typeof(p_input->'archived') is distinct from 'boolean' then perform demo_desktop.fail('invalid-input');end if;
 if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from p_input->>'revision' then perform demo_desktop.fail('conflict');end if;
 if cid is not null then perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);end if;
 at:=case when (p_input->>'archived')::boolean then clock_timestamp()::text else null end;
 if cid is not null then update demo_desktop.customers set data=data||jsonb_build_object('deleted_at',at) where owner_id=p_owner and workspace_id=p_workspace and id=cid;
 else update demo_desktop.graves set data=data||jsonb_build_object('deleted_at',at) where owner_id=p_owner and workspace_id=p_workspace and id=gid;end if;
 perform demo_desktop.bump(p_owner,p_workspace,cid,gid);
 return jsonb_build_object('customerId',cid,'graveId',gid,'deletedAt',at);
end $$;
create or replace function demo_desktop.permanent_delete(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare cid bigint:=(p_input->>'customerId')::bigint;gid bigint:=(p_input->>'graveId')::bigint;ids bigint[];counter_name text;maximum bigint;begin
 if p_input-array['type','customerId','graveId','revision']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from p_input->>'revision' then perform demo_desktop.fail('conflict');end if;
 if cid is not null then
  perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
  if not exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  select array_agg(id) into ids from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid;
 else
  if not exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  ids:=array[gid];
 end if;
 foreach counter_name in array array['customers','graves','payments'] loop
  execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',counter_name) into maximum using p_owner,p_workspace;
  insert into demo_desktop.id_counters(owner_id,workspace_id,name,high_water) values(p_owner,p_workspace,counter_name,maximum) on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 end loop;
 delete from demo_desktop.locations where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(ids);
 delete from demo_desktop.earth_links where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(ids);
 delete from demo_desktop.payments where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(ids);
 delete from demo_desktop.annual_work where owner_id=p_owner and workspace_id=p_workspace and (customer_id=cid or grave_id=any(ids));
 delete from demo_desktop.work_rows where owner_id=p_owner and workspace_id=p_workspace and ((data->>'customerId')::bigint=cid or (data->>'graveId')::bigint=any(ids));
 delete from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=any(ids);
 if cid is not null then delete from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;end if;
 return jsonb_build_object('customerId',cid,'graveId',gid);
end $$;

create or replace function demo_desktop.delete_work(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$declare r jsonb;cid bigint:=(p_input->>'customerId')::bigint;y integer:=(p_input->>'year')::integer;begin
 if p_input-array['type','year','customerId','key','revision']<>'{}' or jsonb_typeof(p_input->'year') is distinct from 'number' or (p_input->>'year')::numeric<>y or y not between 1 and 9999 then perform demo_desktop.fail('invalid-input');end if;
 r:=demo_desktop.sales_contact(p_owner,p_workspace,cid,y);
 if r is null or r->>'revision' is distinct from p_input->>'revision' or r->>'key' is distinct from p_input->>'key' or coalesce(r->>'key','')='' or r->>'deleted_at' is not null or r->>'workDeletedAt' is not null then perform demo_desktop.fail('conflict');end if;
 perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
 update demo_desktop.annual_work set deleted_at=clock_timestamp()::text,version=version+1 where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid and year=y;
 perform demo_desktop.bump(p_owner,p_workspace,cid,(r->>'graveId')::bigint);return jsonb_build_object('customerId',cid,'year',y,'key',r->>'key');
end $$;
create or replace function public.demo_desktop_command(p_workspace uuid,p_session uuid,p_request uuid,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;a uuid:=auth.uid();fingerprint text;previous demo_desktop.requests;result jsonb;begin
 o:=demo_desktop.assert_actor(p_workspace);
 if p_session is null or p_request is null or jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>20000000 then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 case p_input->>'type'
 when 'location-save' then if p_input ? 'approve' then result:=demo_desktop.review_location(o,p_workspace,p_session,p_input);else result:=demo_desktop.save_location(o,p_workspace,p_session,p_input);end if;
 when 'earth-prepare' then result:=demo_desktop.prepare_earth(o,p_workspace,p_session,p_input);
 when 'earth-connect' then result:=demo_desktop.connect_earth(o,p_workspace,p_session,p_input);
 when 'register' then result:=demo_desktop.register(o,p_workspace,p_input);
 when 'update-customers' then result:=demo_desktop.update_customers(o,p_workspace,p_session,p_input);
 when 'archive' then result:=demo_desktop.archive(o,p_workspace,p_session,p_input);
 when 'permanent-delete' then result:=demo_desktop.permanent_delete(o,p_workspace,p_session,p_input);
 when 'work-delete' then result:=demo_desktop.delete_work(o,p_workspace,p_session,p_input);
 when 'sales-save' then result:=demo_desktop.save_sales(o,p_workspace,p_session,p_input);
 else perform demo_desktop.fail('invalid-input');end case;
 if to_regprocedure('demo_desktop.refresh_sent_amounts(uuid,uuid)') is not null then perform demo_desktop.refresh_sent_amounts(o,p_workspace);end if;
 perform demo_desktop.refresh_projection(o,p_workspace);
 insert into demo_desktop.requests(owner_id,workspace_id,actor_id,request_id,session_id,input_sha,result) values(o,p_workspace,a,p_request,p_session,fingerprint,result);
 return jsonb_build_object('requestId',p_request,'result',result,'snapshot',demo_desktop.snapshot(o,p_workspace));
end $$;
create or replace function public.demo_desktop_result(p_workspace uuid,p_request uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare o uuid;r jsonb;begin
 o:=demo_desktop.assert_actor(p_workspace);
 select result into r from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=auth.uid() and request_id=p_request;
 if not found then return jsonb_build_object('state','not-found','requestId',p_request);end if;
 return jsonb_build_object('state','committed','requestId',p_request,'result',r);
end $$;
