create or replace function demo_desktop.expire_assignments(p_owner uuid,p_workspace uuid) returns void language plpgsql set search_path='' as $$begin
 update demo_desktop.sales_assignments a set state='needs_review' where a.owner_id=p_owner and a.workspace_id=p_workspace and a.state='active'
 and (a.last_seen_at<=clock_timestamp()-interval '90 seconds' or not exists(select from auth.sessions s where s.id=a.auth_session_id and s.user_id=a.actor_id));
end $$;
create or replace function demo_desktop.lease_json(p_lease demo_desktop.sales_assignments) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('customerId',p_lease.customer_id,'sessionId',p_lease.session_id,'token',p_lease.token,'state',p_lease.state,'lastSeenAt',p_lease.last_seen_at);
$$;
create or replace function demo_desktop.assert_editable(p_owner uuid,p_workspace uuid,p_session uuid,p_customer bigint,p_token uuid default null) returns void language plpgsql set search_path='' as $$declare a demo_desktop.sales_assignments;begin
 if not exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=p_customer) then perform demo_desktop.fail('conflict');end if;
 select * into a from demo_desktop.sales_assignments where owner_id=p_owner and workspace_id=p_workspace and customer_id=p_customer;
 if found and a.state<>'released' and (a.state<>'active' or a.actor_id<>auth.uid() or a.auth_session_id<>demo_desktop.auth_session() or a.session_id<>p_session or a.last_seen_at<=clock_timestamp()-interval '90 seconds' or (p_token is not null and a.token<>p_token)) then perform demo_desktop.fail('lease-unavailable');end if;
end $$;
create or replace function demo_desktop.available_sales_count(p_owner uuid,p_workspace uuid,p_year integer,p_region text) returns bigint language sql stable set search_path='' as $$
 select count(*) from demo_desktop.customers c where c.owner_id=p_owner and c.workspace_id=p_workspace and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year)->>'deleted_at' is null
 and (p_region='*' or demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year)->>'region'=p_region)
 and not exists(select from demo_desktop.annual_work w where w.owner_id=p_owner and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=p_year)
 and not exists(select from demo_desktop.sales_assignments l where l.owner_id=p_owner and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released');
$$;
create or replace function public.demo_sales_assignment(p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);actor uuid:=auth.uid();login_session uuid:=demo_desktop.auth_session();a demo_desktop.sales_assignments;cid bigint;year_value integer;region_value text;after_id bigint;direction_value text;action text:=p_input->>'action';token_value uuid;count_value bigint;reason_value text;begin
 if p_session is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['action','year','region','customerId','token','confirmedEnded','afterCustomerId','direction','reason']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);perform demo_desktop.lock_actor(p_workspace,o);perform demo_desktop.expire_assignments(o,p_workspace);
 if action in ('regions','claim') then
  if jsonb_typeof(p_input->'year') is distinct from 'number' or (p_input->>'year')::numeric not between 1 and 9999 or (p_input->>'year')::numeric<>trunc((p_input->>'year')::numeric) then perform demo_desktop.fail('invalid-input');end if;year_value:=(p_input->>'year')::int;
 end if;
 if action='regions' then
  return jsonb_build_object('year',year_value,'regions',(select coalesce(jsonb_agg(jsonb_build_object('region',region,'availableCount',n) order by region),'[]') from (
   select demo_desktop.region((demo_desktop.sales_contact(o,p_workspace,c.id,year_value))->>'address') region,count(*) n from demo_desktop.customers c
   where c.owner_id=o and c.workspace_id=p_workspace and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(o,p_workspace,c.id,year_value)->>'deleted_at' is null
   and not exists(select from demo_desktop.annual_work w where w.owner_id=o and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=year_value)
   and not exists(select from demo_desktop.sales_assignments l where l.owner_id=o and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released') group by 1) r));
 elsif action='list-review' then
  return jsonb_build_object('rows',(select coalesce(jsonb_agg(jsonb_build_object('customerId',l.customer_id,'name',coalesce(c.data->>'name',''),'state',l.state,'lastSeenAt',l.last_seen_at,'responsible',coalesce(m.display_name,'사장님')) order by l.last_seen_at),'[]') from demo_desktop.sales_assignments l join demo_desktop.customers c on c.owner_id=l.owner_id and c.workspace_id=l.workspace_id and c.id=l.customer_id left join public.demo_members m on m.user_id=l.actor_id where l.owner_id=o and l.workspace_id=p_workspace and l.state='needs_review'));
 elsif action='claim' then
  if jsonb_typeof(p_input->'region') is distinct from 'string' or char_length(p_input->>'region') not between 1 and 500 then perform demo_desktop.fail('invalid-input');end if;
  region_value:=p_input->>'region';after_id:=(p_input->>'afterCustomerId')::bigint;direction_value:=coalesce(p_input->>'direction','next');if direction_value not in ('next','prev') then perform demo_desktop.fail('invalid-input');end if;
  select * into a from demo_desktop.sales_assignments where owner_id=o and workspace_id=p_workspace and actor_id=actor and session_id=p_session and state<>'released';
  if found then
   if a.auth_session_id<>login_session or a.service_year<>year_value or a.state<>'active' or (region_value<>'*' and demo_desktop.sales_contact(o,p_workspace,a.customer_id,year_value)->>'region'<>region_value) then perform demo_desktop.fail('lease-unavailable');end if;
   return jsonb_build_object('row',demo_desktop.sales_contact(o,p_workspace,a.customer_id,year_value),'lease',demo_desktop.lease_json(a),'availableCount',demo_desktop.available_sales_count(o,p_workspace,year_value,region_value));
  end if;
  select c.id into cid from demo_desktop.customers c
  where c.owner_id=o and c.workspace_id=p_workspace and (after_id is null or c.id<>after_id) and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(o,p_workspace,c.id,year_value)->>'deleted_at' is null
   and (region_value='*' or demo_desktop.sales_contact(o,p_workspace,c.id,year_value)->>'region'=region_value)
   and not exists(select from demo_desktop.annual_work w where w.owner_id=o and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=year_value)
   and not exists(select from demo_desktop.sales_assignments l where l.owner_id=o and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released')
  order by case when after_id is null then 0 when direction_value='prev' and c.id<after_id then 0 when direction_value='next' and c.id>after_id then 0 else 1 end,case when direction_value='prev' then -c.id else c.id end limit 1 for update;
  if cid is null then return jsonb_build_object('row',null,'lease',null,'availableCount',0);end if;
  insert into demo_desktop.sales_assignments(owner_id,workspace_id,customer_id,actor_id,auth_session_id,session_id,token,service_year,state,last_seen_at) values(o,p_workspace,cid,actor,login_session,p_session,gen_random_uuid(),year_value,'active',clock_timestamp())
  on conflict(owner_id,workspace_id,customer_id) do update set actor_id=excluded.actor_id,auth_session_id=excluded.auth_session_id,session_id=excluded.session_id,token=excluded.token,service_year=excluded.service_year,state='active',last_seen_at=excluded.last_seen_at,created_at=clock_timestamp() returning * into a;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action) values(o,p_workspace,cid,actor,p_session,'claim');
  return jsonb_build_object('row',demo_desktop.sales_contact(o,p_workspace,cid,year_value),'lease',demo_desktop.lease_json(a),'availableCount',demo_desktop.available_sales_count(o,p_workspace,year_value,region_value));
 end if;
 cid:=(p_input->>'customerId')::bigint;token_value:=(p_input->>'token')::uuid;
 -- A completed original release is a receipt, never permission to release a newer token.
 if action in ('release','heartbeat','resume') and exists(select from demo_desktop.sales_audit receipt where receipt.owner_id=o and receipt.workspace_id=p_workspace and receipt.customer_id=cid and receipt.actor_id=actor and receipt.lease_token=token_value and receipt.action='release' and (receipt.session_id=p_session or p_input->>'action'='resume')) then
  if action='release' and p_input->'confirmedEnded' is distinct from 'true'::jsonb then perform demo_desktop.fail('invalid-input');end if;
  return jsonb_build_object('released',true,'row',null,'lease',null);
 end if;
 select * into a from demo_desktop.sales_assignments where owner_id=o and workspace_id=p_workspace and customer_id=cid for update;
 if not found or a.state='released' then perform demo_desktop.fail('lease-unavailable');end if;
 if action='admin-release' then
  reason_value:=demo_desktop.text_value(p_input,'reason',200);if reason_value is null then perform demo_desktop.fail('invalid-input');end if;
  update demo_desktop.sales_assignments set state='released',token=gen_random_uuid() where owner_id=o and workspace_id=p_workspace and customer_id=cid;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action,reason) values(o,p_workspace,cid,actor,p_session,action,reason_value);
  return jsonb_build_object('released',true);
 end if;
 if a.actor_id<>actor or a.token is distinct from token_value then perform demo_desktop.fail('lease-unavailable');end if;
 if action='resume' then
  if (a.state='active' and (a.session_id<>p_session or a.auth_session_id<>login_session)) or exists(select from demo_desktop.sales_assignments where owner_id=o and workspace_id=p_workspace and actor_id=actor and session_id=p_session and state<>'released' and customer_id<>cid) then perform demo_desktop.fail('lease-unavailable');end if;
  if not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is null and coalesce(data->>'registration_status','registered')='registered') or exists(select from demo_desktop.annual_work where owner_id=o and workspace_id=p_workspace and customer_id=cid and year=a.service_year) then perform demo_desktop.fail('lease-unavailable');end if;
  update demo_desktop.sales_assignments set state='active',auth_session_id=login_session,session_id=p_session,token=gen_random_uuid(),last_seen_at=clock_timestamp() where owner_id=o and workspace_id=p_workspace and customer_id=cid returning * into a;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action) values(o,p_workspace,cid,actor,p_session,'resume');
 elsif a.session_id<>p_session or a.auth_session_id<>login_session then perform demo_desktop.fail('lease-unavailable');
 elsif action='heartbeat' then
  if a.state='active' then
   if not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is null and coalesce(data->>'registration_status','registered')='registered') then perform demo_desktop.fail('lease-unavailable');end if;
   update demo_desktop.sales_assignments set last_seen_at=clock_timestamp() where owner_id=o and workspace_id=p_workspace and customer_id=cid returning * into a;
  end if;
 elsif action='release' then
  if p_input->'confirmedEnded' is distinct from 'true'::jsonb then perform demo_desktop.fail('invalid-input');end if;
  update demo_desktop.sales_assignments set state='released',token=gen_random_uuid() where owner_id=o and workspace_id=p_workspace and customer_id=cid;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action,lease_token) values(o,p_workspace,cid,actor,p_session,'release',token_value);return jsonb_build_object('released',true);
 else perform demo_desktop.fail('invalid-input');end if;
 return jsonb_build_object('row',case when a.state='active' then demo_desktop.sales_contact(o,p_workspace,cid,a.service_year) else null end,'lease',demo_desktop.lease_json(a),'availableCount',0);
end $$;
create or replace function demo_desktop.save_sales(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$
declare cid bigint:=(p_input->>'customerId')::bigint;year_value integer;token_value uuid:=(p_input->>'leaseToken')::uuid;context_value text:=coalesce(p_input->>'context','sales');r jsonb;c jsonb;v jsonb;amount bigint;task demo_desktop.annual_work;assignment demo_desktop.sales_assignments;status_value text:=p_input->>'status';deadline_value text;gid bigint;begin
 if p_input-array['type','context','key','year','customerId','revision','status','requirements','notes','deadline','currentAmount','leaseToken']<>'{}' or context_value not in ('sales','work') or jsonb_typeof(p_input->'year') is distinct from 'number' or (p_input->>'year')::numeric not between 1 and 9999 or (p_input->>'year')::numeric<>trunc((p_input->>'year')::numeric) or status_value is null or status_value not in ('uncontacted','proceed','declined') or jsonb_typeof(p_input->'notes') is distinct from 'string' or jsonb_typeof(p_input->'deadline') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 year_value:=(p_input->>'year')::int;r:=demo_desktop.sales_contact(p_owner,p_workspace,cid,year_value);gid:=(r->>'graveId')::bigint;
 if r is null or r->>'revision' is distinct from p_input->>'revision' or r->>'deleted_at' is not null or r->>'workDeletedAt' is not null then perform demo_desktop.fail('conflict');end if;
 select data into c from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
 if coalesce(c->>'registration_status','registered')<>'registered' then perform demo_desktop.fail('conflict');end if;
 select * into task from demo_desktop.annual_work where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid and year=year_value;
 if context_value='work' then
  if task.id is null or p_input->>'key' is distinct from 'annual:'||task.id then perform demo_desktop.fail('conflict');end if;
  perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
 else
  select * into assignment from demo_desktop.sales_assignments where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid;
  if assignment.customer_id is null or task.id is not null or assignment.state<>'active' or assignment.service_year<>year_value or assignment.actor_id<>auth.uid() or assignment.auth_session_id<>demo_desktop.auth_session() or assignment.session_id<>p_session or assignment.token is distinct from token_value or assignment.last_seen_at<=clock_timestamp()-interval '90 seconds' then perform demo_desktop.fail('lease-unavailable');end if;
 end if;
 v:=demo_desktop.edit_values(jsonb_build_object('specialNotes',p_input->>'notes')||case when p_input ? 'requirements' then jsonb_build_object('requirements',p_input->'requirements') else '{}'::jsonb end,c);
 deadline_value:=coalesce(demo_desktop.text_value(p_input,'deadline',200),'');
 if (status_value='proceed' or nullif(p_input->>'currentAmount','') is not null) and gid is null then perform demo_desktop.fail('invalid-input');end if;
 if p_input ? 'currentAmount' then
  amount:=demo_desktop.number_value(p_input,'currentAmount');
  if amount is null and exists(select from demo_desktop.payments where owner_id=p_owner and workspace_id=p_workspace and grave_id=gid and year=year_value and kind='annual') then perform demo_desktop.fail('invalid-input');end if;
 end if;
 update demo_desktop.customers set data=data||jsonb_build_object('special_notes',v->'specialNotes')||case when p_input ? 'requirements' then jsonb_build_object('memo',v->'requirements') else '{}'::jsonb end where owner_id=p_owner and workspace_id=p_workspace and id=cid;
 if task.id is null then
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,data) values(p_owner,p_workspace,gen_random_uuid(),year_value,cid,gid,status_value,jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline',deadline_value));
 else update demo_desktop.annual_work a set grave_id=gid,status=status_value,data=a.data||jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline',deadline_value),version=a.version+1 where a.owner_id=p_owner and a.workspace_id=p_workspace and a.id=task.id;end if;
 if amount is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,year_value,'annual',amount,'desktop_sales');end if;
 perform demo_desktop.bump(p_owner,p_workspace,cid,gid);
 if context_value='sales' then
  update demo_desktop.sales_assignments set state='released',token=gen_random_uuid() where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action) values(p_owner,p_workspace,cid,auth.uid(),p_session,'save');
 end if;
 return jsonb_build_object('customerId',cid,'graveId',gid,'year',year_value);
end $$;
