create trigger desktop_earth_grave_removed before delete on demo_desktop.graves for each row execute function demo_desktop.earth_grave_removed();

create or replace function demo_desktop.prepare_earth(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$
declare target jsonb:=p_input->'target';cid bigint;gid bigint;manifest jsonb;prep uuid:=gen_random_uuid();vid uuid:=(p_input->>'versionId')::uuid;s jsonb:=p_input->'selection';o jsonb:=p_input->'original';begin
 if p_input-array['type','target','selection','original','versionId','importedAt']<>'{}' or jsonb_typeof(target) is distinct from 'object' or target-array['newCustomer','customerId','graveId','revision','originalAddress','previousVersion']<>'{}' or jsonb_typeof(target->'originalAddress') is distinct from 'string' or char_length(target->>'originalAddress')>4000 then perform demo_desktop.fail('invalid-input');end if;
 if target->'newCustomer'='true'::jsonb then
  if target-array['newCustomer','originalAddress']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  cid:=demo_desktop.next_id(p_owner,p_workspace,'customers');gid:=demo_desktop.next_id(p_owner,p_workspace,'graves');
 else
  cid:=(target->>'customerId')::bigint;gid:=(target->>'graveId')::bigint;
  if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from target->>'revision' or not exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid and customer_id is not distinct from cid and coalesce(data->>'address','')=target->>'originalAddress' and nullif(data->>'deleted_at','') is null) then perform demo_desktop.fail('conflict');end if;
  if cid is not null then perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);end if;
 end if;
 if jsonb_typeof(o) is distinct from 'object' or not o ?& array['sourceFile','sha256','size'] or o-array['sourceFile','sha256','size']<>'{}' or o->>'sha256'!~'^[a-f0-9]{64}$' or o->>'sourceFile'!~*'^.+\.(kml|kmz)$' or o->>'sourceFile'~'[<>:"/\\|?*[:cntrl:]]' or char_length(o->>'sourceFile')>255 or jsonb_typeof(o->'size') is distinct from 'number' or (o->>'size')::numeric not between 1 and 5242880 or (o->>'size')::numeric<>trunc((o->>'size')::numeric) then perform demo_desktop.fail('invalid-input');end if;
 if jsonb_typeof(s) is distinct from 'object' or not s ?& array['name','geometry','point','areaM2'] or not p_input ? 'importedAt' or s-array['name','geometry','point','areaM2']<>'{}' or jsonb_typeof(s->'name') is distinct from 'string' or char_length(s->>'name') not between 1 and 500 or s->'geometry'->>'type' not in ('Point','Polygon') or jsonb_typeof(s->'geometry'->'coordinates') is distinct from 'array' or jsonb_typeof(s->'point'->'lat') is distinct from 'number' or jsonb_typeof(s->'point'->'lng') is distinct from 'number' or (s->'point'->>'lat')::numeric not between -90 and 90 or (s->'point'->>'lng')::numeric not between -180 and 180 or (s->'areaM2'<>'null'::jsonb and (jsonb_typeof(s->'areaM2') is distinct from 'number' or (s->>'areaM2')::numeric<=0)) or p_input->>'importedAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then perform demo_desktop.fail('invalid-input');end if;
 manifest:=jsonb_build_object('format','demo-earth-asset','schemaVersion',1,'workspaceId',p_workspace,'graveId',gid,'versionId',vid,'originalAddress',target->'originalAddress','importedAt',p_input->'importedAt','sourceFile',o->'sourceFile','sha256',o->'sha256','size',o->'size','selection',s);
 insert into demo_desktop.earth_candidates(owner_id,workspace_id,id,actor_id,customer_id,grave_id,version_id,target,manifest) values(p_owner,p_workspace,prep,auth.uid(),cid,gid,vid,target,manifest);
 perform demo_desktop.asset_write(p_owner,p_workspace,auth.uid(),manifest,vid,'reserve');
 return jsonb_build_object('preparationId',prep,'versionId',vid,'customerId',cid,'graveId',gid,'manifest',manifest);
end $$;
create or replace function demo_desktop.connect_earth(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb,p_registration boolean default false) returns jsonb language plpgsql set search_path='' as $$declare c demo_desktop.earth_candidates;old_version uuid;summary jsonb;begin
 if not p_registration and p_input-array['type','preparationId']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 select * into c from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and id=(p_input->>'preparationId')::uuid and actor_id=auth.uid() for update;
 if not found or c.state<>'prepared' then perform demo_desktop.fail('conflict');end if;
 if p_registration is distinct from (c.target->'newCustomer'='true'::jsonb) and coalesce((c.target->>'newCustomer')::boolean,false)<>p_registration then perform demo_desktop.fail('conflict');end if;
 if not exists(select from public.demo_earth_assets where owner_id=p_owner and workspace_id=p_workspace and version_id=c.version_id and state='ready' and retired_at is null) then perform demo_desktop.fail('conflict');end if;
 if not p_registration and demo_desktop.entity_revision(p_owner,p_workspace,c.customer_id,c.grave_id) is distinct from c.target->>'revision' then perform demo_desktop.fail('conflict');end if;
 if not exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=c.grave_id and customer_id is not distinct from c.customer_id and coalesce(data->>'address','')=c.target->>'originalAddress' and nullif(data->>'deleted_at','') is null) or exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=c.customer_id and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
 if c.customer_id is not null then perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,c.customer_id);end if;
 select version_id into old_version from demo_desktop.earth_links where owner_id=p_owner and workspace_id=p_workspace and grave_id=c.grave_id;
 if not p_registration and old_version::text is distinct from c.target->>'previousVersion' then perform demo_desktop.fail('conflict');end if;
 summary:=c.manifest->'selection'||jsonb_build_object('graveId',c.grave_id,'originalAddress',c.target->'originalAddress','source','google_earth_kml','confirmedAt',clock_timestamp()::text,'versionId',c.version_id,'revision',c.version_id::text,'sourceFile',c.manifest->'sourceFile','asset',jsonb_build_object('versionId',c.version_id,'sha256',c.manifest->'sha256','size',c.manifest->'size','sourceFile',c.manifest->'sourceFile','state','ready'));
 insert into demo_desktop.earth_links(owner_id,workspace_id,grave_id,version_id,data) values(p_owner,p_workspace,c.grave_id,c.version_id,summary) on conflict(owner_id,workspace_id,grave_id) do update set version_id=excluded.version_id,data=excluded.data;
 update demo_desktop.graves set data=data||jsonb_build_object('pyeong',case when c.manifest->'selection'->'areaM2'='null'::jsonb then data->'pyeong' else to_jsonb(round((c.manifest->'selection'->>'areaM2')::numeric/3.305785,2)) end) where owner_id=p_owner and workspace_id=p_workspace and id=c.grave_id;
 update demo_desktop.earth_candidates set state='connected' where owner_id=p_owner and workspace_id=p_workspace and id=c.id;
 perform demo_desktop.bump(p_owner,p_workspace,c.customer_id,c.grave_id);
 return jsonb_build_object('customerId',c.customer_id,'graveId',c.grave_id,'record',summary);
end $$;

-- The Edge service passes an already verified actor and a still-existing auth session.
create or replace function public.demo_desktop_earth_access(p_workspace uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare o uuid;begin
 o:=demo_desktop.assert_actor(p_workspace);return jsonb_build_object('id',auth.uid(),'ownerId',o,'workspaceId',p_workspace,'role',case when o=auth.uid() then 'owner' else 'master' end,'authSessionId',demo_desktop.auth_session(),'shared',exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active));end $$;
revoke all on function public.demo_desktop_earth_access(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_earth_access(uuid) to authenticated;
create or replace function public.demo_desktop_earth_asset(p_owner uuid,p_workspace uuid,p_actor uuid,p_auth_session uuid,p_action text,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare c demo_desktop.earth_candidates;vid uuid;row_value jsonb;v record;result jsonb:='[]';begin
 if not public.demo_earth_actor(p_owner,p_workspace,p_actor) or not exists(select from auth.sessions where id=p_auth_session and user_id=p_actor) then raise exception 'Earth upload permission required';end if;
 perform demo_desktop.lock_company(p_owner,p_workspace);
 perform 1 from auth.sessions where id=p_auth_session and user_id=p_actor for key share;
 if not found or not public.demo_earth_actor(p_owner,p_workspace,p_actor) then raise exception 'Earth upload permission required';end if;
 if p_action='protected' then
  select coalesce(jsonb_agg(jsonb_build_object('sha256',manifest->'sha256','size',manifest->'size','sourceFile',manifest->'sourceFile')),'[]') into result from public.demo_earth_assets where owner_id=p_owner and workspace_id=p_workspace and retired_at is null;return result;
 end if;
 if p_action='cleanup' then
  for v in select id,version_id from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and state='prepared' and created_at<clock_timestamp()-interval '24 hours' loop
   update demo_desktop.earth_candidates set state='cancelled' where owner_id=p_owner and workspace_id=p_workspace and id=v.id;perform demo_desktop.retire_unlinked(p_owner,p_workspace,v.version_id);
  end loop;
  for v in select j.version_id from demo_desktop.earth_cleanup j where j.owner_id=p_owner and j.workspace_id=p_workspace order by j.last_checked_at nulls first,j.version_id limit 100 loop
   if exists(select from demo_desktop.earth_links where owner_id=p_owner and workspace_id=p_workspace and version_id=v.version_id) then raise exception 'Earth referenced version conflict';end if;
   update demo_desktop.earth_cleanup set attempts=attempts+1 where owner_id=p_owner and workspace_id=p_workspace and version_id=v.version_id;
   select to_jsonb(a) into row_value from public.demo_earth_assets a where owner_id=p_owner and workspace_id=p_workspace and version_id=v.version_id and retired_at is not null;result:=result||jsonb_build_array(row_value);
  end loop;return result;
 end if;
 vid:=(p_input->>'versionId')::uuid;
 if p_action='ack' then
  perform demo_desktop.asset_write(p_owner,p_workspace,p_actor,null,vid,'ack');update demo_desktop.earth_cleanup set last_checked_at=clock_timestamp() where owner_id=p_owner and workspace_id=p_workspace and version_id=vid;return '{}';
 end if;
 if p_action in ('begin','publish') then
  select * into c from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and version_id=vid and actor_id=p_actor;
  if not found or c.state='cancelled' or (p_action='begin' and (p_input->>'preparationId')::uuid is distinct from c.id) or (p_action='begin' and p_input->'manifest'<>c.manifest) then raise exception 'Earth retired version conflict';end if;
  return demo_desktop.asset_write(p_owner,p_workspace,p_actor,case when p_action='begin' then c.manifest else null end,vid,case when p_action='publish' then 'publish' else 'reserve' end);
 elsif p_action='get' then
  select to_jsonb(a) into result from public.demo_earth_assets a where owner_id=p_owner and workspace_id=p_workspace and version_id=vid and (exists(select from demo_desktop.earth_links where owner_id=p_owner and workspace_id=p_workspace and version_id=vid) or exists(select from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and version_id=vid and actor_id=p_actor and state<>'cancelled'));return result;
 end if;
 raise exception 'Invalid Earth action';
end $$;
revoke all on function public.demo_desktop_earth_asset(uuid,uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.demo_desktop_earth_asset(uuid,uuid,uuid,uuid,text,jsonb) to service_role;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;
create or replace function demo_desktop.save_location(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$declare cid bigint:=(p_input->>'customerId')::bigint;gid bigint:=(p_input->>'graveId')::bigint;l jsonb:=p_input->'location';d jsonb;begin
 if p_input-array['type','customerId','graveId','revision','originalAddress','lookupAddress','location']<>'{}' or demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from p_input->>'revision' then perform demo_desktop.fail('conflict');end if;
 if cid is not null then perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);end if;
 if not exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid and coalesce(data->>'address','')=p_input->>'originalAddress' and nullif(data->>'deleted_at','') is null) or exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
 if jsonb_typeof(p_input->'lookupAddress') is distinct from 'string' or char_length(p_input->>'lookupAddress')>500 or (l<>'null'::jsonb and (jsonb_typeof(l) is distinct from 'object' or not l ?& array['lat','lng','source'] or jsonb_typeof(l->'lat') is distinct from 'number' or jsonb_typeof(l->'lng') is distinct from 'number' or (l->>'lat')::numeric not between -90 and 90 or (l->>'lng')::numeric not between -180 and 180 or l->>'source' not in ('field','public_parcel') or l-array['lat','lng','source','pnu','matchedAddress','datasetDate']<>'{}')) then perform demo_desktop.fail('invalid-input');end if;
 if l->>'source'='public_parcel' and (l->>'pnu'!~'^[0-9]{19}$' or coalesce(l->>'matchedAddress','')='' or char_length(l->>'matchedAddress')>500 or l->>'datasetDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then perform demo_desktop.fail('invalid-input');end if;
 d:=jsonb_build_object('id',gid,'address',p_input->'originalAddress','lookupAddress',p_input->'lookupAddress','location',l,'updatedAt',clock_timestamp()::text);
 insert into demo_desktop.locations(owner_id,workspace_id,grave_id,data) values(p_owner,p_workspace,gid,d) on conflict(owner_id,workspace_id,grave_id) do update set data=excluded.data;
 perform demo_desktop.bump(p_owner,p_workspace,cid,gid);return d;
end $$;
-- Prevent legacy rejection/approval from bypassing version checks even when it does not write a map.
create or replace function public.demo_desktop_location_gate() returns trigger language plpgsql set search_path='' as $$begin
 if current_user<>'demo_desktop_writer' and exists(select from public.demo_catalogs where owner_id=new.owner_id and workspace_id=new.workspace_id and desktop_shared) and new.status is distinct from old.status then perform public.demo_desktop_write_denied();end if;return new;
end $$;
drop trigger if exists desktop_location_gate on public.demo_location_requests;
create trigger desktop_location_gate before update on public.demo_location_requests for each row execute function public.demo_desktop_location_gate();
grant select,update on public.demo_location_requests to demo_desktop_writer;
drop policy if exists desktop_location_writer on public.demo_location_requests;
create policy desktop_location_writer on public.demo_location_requests for all to demo_desktop_writer using(true) with check(true);
create or replace function demo_desktop.location_review_write(p_id uuid,p_approve boolean,p_actor uuid,p_previous jsonb) returns void language plpgsql security definer set search_path='' as $$begin
 update public.demo_location_requests set status=case when p_approve then 'approved' else 'rejected' end,reviewer_id=p_actor,reviewed_at=clock_timestamp(),previous_location=p_previous where id=p_id;
end $$;
grant create on schema demo_desktop to demo_desktop_writer;
alter function demo_desktop.location_review_write(uuid,boolean,uuid,jsonb) owner to demo_desktop_writer;
revoke create on schema demo_desktop from demo_desktop_writer;
grant execute on function demo_desktop.location_review_write(uuid,boolean,uuid,jsonb) to postgres;
create or replace function demo_desktop.review_location(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$declare r public.demo_location_requests;g demo_desktop.graves;latest bigint;d jsonb;begin
 if p_input-array['type','id','approve','revision']<>'{}' or jsonb_typeof(p_input->'approve') is distinct from 'boolean' then perform demo_desktop.fail('invalid-input');end if;
 select * into r from public.demo_location_requests where owner_id=p_owner and workspace_id=p_workspace and id=(p_input->>'id')::uuid for update;
 if not found or r.status<>'pending' then perform demo_desktop.fail('conflict');end if;
 select * into g from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=r.grave_id;
 if not found or demo_desktop.entity_revision(p_owner,p_workspace,g.customer_id,g.id) is distinct from p_input->>'revision' then perform demo_desktop.fail('conflict');end if;
 if g.customer_id is not null then perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,g.customer_id);end if;
 select data->'location' into d from demo_desktop.locations where owner_id=p_owner and workspace_id=p_workspace and grave_id=g.id;
 if (p_input->>'approve')::boolean then
  if coalesce(g.data->>'address','')<>r.original_address or nullif(g.data->>'deleted_at','') is not null or exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=g.customer_id and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  select coalesce(max(seq),0) into latest from public.demo_location_requests where owner_id=p_owner and workspace_id=p_workspace and grave_id=g.id and status='approved';if latest<>r.base_seq then perform demo_desktop.fail('conflict');end if;
  insert into demo_desktop.locations(owner_id,workspace_id,grave_id,data) values(p_owner,p_workspace,g.id,jsonb_build_object('id',g.id,'address',r.original_address,'lookupAddress',r.original_address,'location',jsonb_build_object('lat',r.latitude,'lng',r.longitude,'source','field','requestId',r.id,'requestSeq',r.seq,'accuracy',r.accuracy,'measuredAt',r.measured_at,'requesterName',r.requester_name))) on conflict(owner_id,workspace_id,grave_id) do update set data=excluded.data;
 end if;
 perform demo_desktop.location_review_write(r.id,(p_input->>'approve')::boolean,auth.uid(),d);
 perform demo_desktop.bump(p_owner,p_workspace,g.customer_id,g.id);return jsonb_build_object('id',r.id);
end $$;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;

-- Shared projections already contain the approved, version-bound private location.
create or replace function public.demo_overlay_field_locations() returns trigger
language plpgsql security definer set search_path='' as $$
declare r record; g jsonb; items jsonb := coalesce(new.payload->'locations','[]');
begin
 if exists(select from public.demo_catalogs where owner_id=new.owner_id and workspace_id=new.workspace_id and desktop_shared) then return new;end if;
 for r in select distinct on(grave_id) * from public.demo_location_requests
 where owner_id=new.owner_id and workspace_id=new.workspace_id and status='approved' order by grave_id,seq desc loop
  g:=public.demo_location_grave(new.owner_id,new.workspace_id,r.grave_id);
  if g is null or g->>'address' is distinct from r.original_address then continue; end if;
  select coalesce(jsonb_agg(item),'[]') into items from jsonb_array_elements(items) item where item->>'id'<>r.grave_id::text;
  items:=items || jsonb_build_array(jsonb_build_object('id',r.grave_id,'address',r.original_address,'region',coalesce(g->>'region','지역 미확인'),'location',jsonb_build_object('lat',r.latitude,'lng',r.longitude,'source','field')));
 end loop;
 -- Stable ordering avoids changing revisions for identical coordinates.
 select coalesce(jsonb_agg(item order by (item->>'id')::bigint),'[]') into items from jsonb_array_elements(items) item;
 new.payload:=jsonb_set(new.payload,'{locations}',items);
 return new;
end $$;

-- Supplemental schema protection. The original demo_schema registry is not rewritten.
create table if not exists demo_desktop.schema_releases(version text primary key,source_sha256 text not null,target jsonb not null,applied_at timestamptz not null default clock_timestamp());
create table if not exists demo_desktop.schema_pending(id boolean primary key default true check(id),xid bigint not null,version text not null,source_sha256 text not null,target jsonb not null);
do $$declare t text;begin
 foreach t in array array['schema_releases','schema_pending'] loop
  if not (select relrowsecurity from pg_class where oid=to_regclass('demo_desktop.'||t)) then execute format('alter table demo_desktop.%I enable row level security',t);end if;
  execute format('revoke all on demo_desktop.%I from public,anon,authenticated,service_role',t);
  if exists(select from pg_roles where rolname='demo_desktop_writer') then execute format('revoke all on demo_desktop.%I from demo_desktop_writer',t);end if;
 end loop;
end $$;
create or replace function demo_desktop.schema_fingerprint(p_key text) returns jsonb
language plpgsql stable set search_path='' as $$declare kind text:=split_part(p_key,':',1);name text:=substr(p_key,strpos(p_key,':')+1);oid_value oid;value jsonb;begin
 if kind='function' then return demo_schema.fingerprint(name);
 elsif kind='table' then
  oid_value:=to_regclass(name);if oid_value is null then return null;end if;
  select jsonb_build_object('rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'owner',r.rolname,
   'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
   'constraints',(select coalesce(jsonb_agg(jsonb_build_array(n.conname,pg_get_constraintdef(n.oid,true),n.convalidated) order by n.conname collate "C"),'[]') from pg_constraint n where n.conrelid=c.oid and n.contype<>'n'),
   'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when v=0 then 'PUBLIC' else (v::regrole)::text end order by v) from unnest(p.polroles) v),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname collate "C"),'[]') from pg_policy p where p.polrelid=c.oid),
   'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end,a.privilege_type,a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end collate "C",a.privilege_type collate "C"),'[]') from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a)) into value from pg_class c join pg_roles r on r.oid=c.relowner where c.oid=oid_value;
  return value;
 elsif kind='schema' then
  select jsonb_build_object('owner',(n.nspowner::regrole)::text,'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end,a.privilege_type,a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end collate "C",a.privilege_type collate "C"),'[]') from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) into value from pg_namespace n where n.nspname=name;return value;
 elsif kind='index' then
  select jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) into value from pg_index i where i.indexrelid=to_regclass(name);return value;
 elsif kind='trigger' then
  select jsonb_build_object('definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) into value from pg_trigger t where t.tgrelid=to_regclass(split_part(name,':',1)) and t.tgname=split_part(name,':',2);return value;
 elsif kind='role' then
  select jsonb_build_object('superuser',r.rolsuper,'login',r.rolcanlogin,'createDb',r.rolcreatedb,'createRole',r.rolcreaterole,'inherit',r.rolinherit,'replicate',r.rolreplication,'bypassRls',r.rolbypassrls,
   'members',(select coalesce(jsonb_agg(jsonb_build_array(m.member_name,case when m.member_name='postgres' then true else m.admin_option end,m.inherit_option,m.set_option) order by m.member_name collate "C"),'[]') from (select (g.member::regrole)::text member_name,bool_or(g.admin_option) admin_option,bool_or(g.inherit_option) inherit_option,bool_or(g.set_option) set_option from pg_auth_members g where g.roleid=r.oid group by g.member) m)) into value from pg_roles r where r.rolname=name;return value;
 elsif kind='event-trigger' then
  select jsonb_build_object('event',evtevent,'enabled',evtenabled,'tags',evttags,'function',evtfoid::regprocedure::text) into value from pg_event_trigger where evtname=name;return value;
 end if;
 raise exception 'Unknown protected desktop object';
end $$;
create or replace function demo_desktop.schema_targets() returns jsonb language plpgsql stable set search_path='' as $$declare result jsonb;begin
 select jsonb_object_agg(key,demo_desktop.schema_fingerprint(key)) into result from (
  select 'function:'||n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')' key from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='demo_desktop' or (n.nspname='public' and (p.proname like 'demo_desktop_%' or p.proname='demo_sales_assignment'))
  union all select 'table:'||n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='demo_desktop' and c.relkind='r'
  union all select 'index:'||n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='demo_desktop' and c.relkind='i'
  union all select unnest(array['schema:demo_desktop','function:public.demo_access(uuid)','function:public.demo_can_manage(uuid,uuid)','function:public.demo_is_staff()','function:public.demo_desktop_access(uuid,uuid,text)','function:public.demo_overlay_field_locations()','table:public.demo_location_requests','trigger:public.demo_location_requests:desktop_location_gate','table:public.demo_earth_assets','trigger:public.demo_earth_assets:desktop_earth_gate','trigger:demo_desktop.earth_links:desktop_earth_retire','trigger:demo_desktop.graves:desktop_earth_grave_removed','table:public.demo_catalogs','table:public.demo_map_snapshots','trigger:public.demo_catalogs:desktop_catalog_gate','trigger:public.demo_map_snapshots:desktop_map_gate','trigger:demo_desktop.schema_pending:desktop_release_must_finish','trigger:public.demo_events:aaa_desktop_event_lock','trigger:public.demo_events:desktop_billed_amounts','index:public.desktop_event_claim_reference','role:demo_desktop_writer','event-trigger:demo_desktop_guard_ddl','event-trigger:demo_desktop_guard_drop'])
 ) targets;
 return result;
end $$;
create or replace function demo_desktop.assert_schema() returns void language plpgsql set search_path='' as $$declare target jsonb;item record;begin
 perform pg_advisory_xact_lock(hashtextextended('demo-schema-application',0));
 perform pg_advisory_xact_lock(hashtextextended('demo-desktop-application',0));
 perform demo_schema.assert_current();
 -- Only the administrator's staged transaction can expose intermediate DDL; COMMIT validates every final fingerprint.
 if exists(select from demo_desktop.schema_pending where xid=txid_current()) then return;end if;
 select r.target into target from demo_desktop.schema_releases r order by r.version desc limit 1;
 if target is null then return;end if;
 for item in select * from jsonb_each(target) loop
  if demo_desktop.schema_fingerprint(item.key) is distinct from item.value then raise exception 'Protected desktop object changed: %',item.key;end if;
 end loop;
 if exists(select from demo_desktop.schema_pending) then raise exception 'Unfinished desktop schema release';end if;
end $$;
create or replace function demo_desktop.begin_upgrade(p_version text,p_sha text,p_expected jsonb,p_target jsonb) returns boolean
language plpgsql set search_path='' as $$declare current_release demo_desktop.schema_releases;begin
 perform demo_desktop.assert_schema();
